from pathlib import Path
import yaml
BASE=Path(__file__).resolve().parents[3]
yaml.SafeDumper.ignore_aliases = lambda *args: True
D=BASE/'assignments/dvizhok-form-context';D.mkdir(exist_ok=True)
checks=[]
F=[('CRM','Сделка','Сделка','новая'),('Продажи','Заказ','Заказ','новый'),('Товары','Отгрузка','Отгрузка','новая'),('Товары','ПоступлениеТоваров','Поступление товаров','новое'),('Финансы','ПоступлениеДенежныхСредств','Поступление денежных средств','новое'),('Финансы','РасходДенежныхСредств','Расход денежных средств','новый'),('Финансы','СчетНаОплату','Счёт на оплату','новый')]
def check(ns,name,method,context,args,observe,expected,tag,**kw):
 c={'scenario':tag,'id':name+'_'+tag,'type':'runtime','points':1,'target':{'module':name+'ФормаОбъекта','namespace':ns,'method':method},'context':context,'lifecycle':{'isNew':False},'args':args,'observe':observe,'expected':expected,'trace':True,**kw}
 checks.append(c);return c
for ns,name,title,gender in F:
 for new,num,arch in [(True,'',False),(True,'42',True),(False,'',True),(False,'42',False)]:
  ctx={'Объект':{'Номер':num}}
  obs=['ЗаголовокФормы','Объект.Номер','РедактированиеДанных','ПредставлениеРедактированиеДанных']
  exp={'ЗаголовокФормы':f'{title} ({gender})' if new else f'{title} (№{num})','Объект.Номер':num,'РедактированиеДанных':False,'ПредставлениеРедактированиеДанных':'Разрешить редактирование реквизитов'}
  if name in ('Сделка','Заказ'):
   ctx['Объект']['Архивный']=arch;obs+=['ПредставлениеАрхивирования','Объект.Архивный'];exp.update({'ПредставлениеАрхивирования':'Вернуть из архива' if arch else 'Архивировать','Объект.Архивный':arch})
  if name=='Отгрузка':
   ctx.update(СозданныйНаЧасти=arch,КоличествоВыбранныхСтрок=2 if new else 0,КоличествоТоваров=3.5 if new else 0,СуммаВыбранныхТоваров=12.25 if new else 0,ТекстИтоговЧасти='seed')
   obs+=['ТекстИтоговЧасти','СозданныйНаЧасти','КоличествоТоваров'];exp.update({'ТекстИтоговЧасти':('Выбрано строк: 2; товаров: 3.5; сумма: 12.25' if new else 'Выбрано строк: 0; товаров: 0; сумма: 0') if arch else 'seed','СозданныйНаЧасти':arch,'КоличествоТоваров':3.5 if new else 0})
  check(ns,name,'ПослеСоздания',ctx,[],obs,exp,f'create_{int(new)}_{num or "empty"}',lifecycle={'isNew':new})
 for enabled in [False,True]:
  ctx={'Объект':{'Номер':'same'},'РедактированиеДанных':enabled,'ЗаголовокФормы':'untouched','ПредставлениеРедактированиеДанных':'Запретить редактирование реквизитов' if enabled else 'Разрешить редактирование реквизитов'}
  obs=['РедактированиеДанных','ПредставлениеРедактированиеДанных','ЗаголовокФормы','Объект.Номер']
  def state(e):return {'РедактированиеДанных':e,'ПредставлениеРедактированиеДанных':'Запретить редактирование реквизитов' if e else 'Разрешить редактирование реквизитов','ЗаголовокФормы':'untouched','Объект.Номер':'same'}
  method='ПредставлениеРедактированиеДанныхОбработчик'
  check(ns,name,method,ctx,[{}],obs,state(not enabled),f'toggle_{int(enabled)}')
  check(ns,name,method,ctx,[{}],obs,{'actions':[state(not enabled),state(enabled)]},f'twice_{int(enabled)}',sequence=[{'method':method,'args':[{}]},{'method':method,'args':[{}]}])
for ns,name in [('CRM','Сделка'),('Продажи','Заказ')]:
 for arch in [False,True]:
  check(ns,name,'ОбновитьПредставлениеАрхивирования',{'Объект':{'Архивный':arch},'ЗаголовокФормы':'untouched'},[],['ПредставлениеАрхивирования','Объект.Архивный','ЗаголовокФормы'],{'ПредставлениеАрхивирования':'Вернуть из архива' if arch else 'Архивировать','Объект.Архивный':arch,'ЗаголовокФормы':'untouched'},f'archive_{int(arch)}')
# Independently specified sums, cardinality, fractional formatting, duplicate rows retained.
for tag,rows,count,total in [('empty',[],0,'0'),('one',[{'Сумма':7}],1,'7'),('fraction',[{'Сумма':2.25},{'Сумма':3.5},{'Сумма':2.25}],3,'8')]:
 check('CRM','Сделка','СуммаОтмеченногоСпросаОбработчик',{'Объект':{'ПервичныйСпрос':rows}},[{}, {'contextPath':'Объект.ПервичныйСпрос'}],['Компоненты.НадписьСуммаСпроса.Значение','Объект.ПервичныйСпрос'],{'Компоненты.НадписьСуммаСпроса.Значение':f'Отмечено строк: {count}; сумма: {total}','Объект.ПервичныйСпрос':[{'ОписаниеПотребностиКлиента':'','Сумма':r['Сумма'],'ПроцентУдовлетворения':0,'ПричинаНеудовлетворения':'','Комментарий':''} for r in rows]},'demand_'+tag)
for tag,rows in [('empty',[]),('several',[{}, {}, {}])]:
 check('CRM','Сделка','ПосчитатьУчастниковОбработчик',{'Объект':{'Участники':rows}},[{}, {'contextPath':'Объект.Участники'}],['Компоненты.НадписьКоличествоУчастников.Значение','Объект.Участники'],{'Компоненты.НадписьКоличествоУчастников.Значение':f'Отмечено участников: {len(rows)}','Объект.Участники':[{'ВыигралСделку':False,'Партнер':None,'Комментарий':''} for r in rows]},'participants_'+tag)
for tag,rows,counts,total,text in [('empty',[],0,0,'Строк: 0; товаров: 0; сумма: 0'),('several',[{'Количество':2,'Сумма':7},{'Количество':3,'Сумма':9}],5,16,'Строк: 2; товаров: 5; сумма: 16'),('fraction',[{'Количество':1.25,'Сумма':2.25},{'Количество':2.5,'Сумма':3.5}],3.75,5.75,'Строк: 2; товаров: 3.75; сумма: 5.75')]:
 check('Продажи','Заказ','ИтогиОтмеченныхОбработчик',{'Объект':{'Товары':rows}},[{}, {'contextPath':'Объект.Товары'}],['Компоненты.НадписьИтогиОтмеченных.Значение','Объект.Товары'],{'Компоненты.НадписьИтогиОтмеченных.Значение':text,'Объект.Товары':[{'Номенклатура':None,'Количество':r['Количество'],'Цена':0,'Сумма':r['Сумма']} for r in rows]},'totals_'+tag)
 check('Продажи','Заказ','РассчитатьИтоги',{'Объект':{}},[rows],['ЗаголовокФормы'],{'return':{'Строк':len(rows),'Товаров':counts,'Сумма':total},'context':{'ЗаголовокФормы':''}},'helper_'+tag)
# Explicit boundaries followed by a supported root.
for ns,name,method in [('CRM','Сделка','АрхивироватьОбработчик'),('Продажи','Заказ','АрхивироватьОбработчик'),('Продажи','Заказ','ОтгрузитьОбработчик')]:
 check(ns,name,method,{'Объект':{}},[{},[]] if method=='ОтгрузитьОбработчик' else [{}],['ЗаголовокФормы'],{},'unsupported_'+method)
 check(ns,name,'ПослеСоздания',{'Объект':{}},[],['ЗаголовокФормы'],{'ЗаголовокФормы':('Сделка' if name=='Сделка' else 'Заказ')+' (№)'},'after_'+method)
(D/'assignment.yaml').write_text(yaml.safe_dump({'name':'Dvizhok: контекст семи форм объектов','checks':checks},allow_unicode=True,sort_keys=False))
print(len(checks))
